package com.bhagya.qa.performance;
public class PerformanceRunner {public static void main(String[]args)throws Exception{DemoService s=new DemoService();s.start();try{int users=args.length>0?Integer.parseInt(args[0]):10;int req=args.length>1?Integer.parseInt(args[1]):10;String scenario=args.length>2?args[2]:"LOAD";PerformanceResult r=new LoadTestEngine().execute("http://127.0.0.1:"+s.getPort(),users,req,scenario);new ReportWriter().write(r);System.out.printf("Run complete: %d/%d successful, P95 %d ms, %.2f req/s%n",r.successfulRequests,r.totalRequests,r.p95Ms,r.throughputPerSecond);System.out.println("Reports: ./reports");}finally{s.stop();}}}
